validator:
function validate(input) {
  const [{ Scores = [] }] = input;
  const keys = new Set();
  for (const [student, subject, score, date] of Scores) {
    if (student === null || subject === null || score === null || date === null) return 'Every column needs a value.';
    if (score < 0 || score > 100) return `Score ${score} is outside 0..100.`;
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) return `exam_date ${date} is not YYYY-MM-DD.`;
    const key = `${student}|${String(subject).toLowerCase()}|${date}`;
    if (keys.has(key)) return `Student ${student} has two ${subject} exams on ${date}.`;
    keys.add(key);
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const pick = n => Math.floor(rand() * n);
  const subjects = small ? ['Math', 'Physics', 'Chemistry'] : ['Math', 'Physics', 'Chemistry', 'Biology', 'History', 'Art'];
  const dates = small
    ? ['2022-12-31', '2023-01-01', '2023-01-15', '2023-02-15', '2023-03-01']
    : Array.from({ length: 24 }, (_, i) => `${2021 + Math.floor(i / 12)}-${String(i % 12 + 1).padStart(2, '0')}-${String(1 + (i * 7) % 28).padStart(2, '0')}`);
  const students = small ? 4 : 400;
  const target = small ? pick(9) : 1500 + pick(501);
  const seen = new Set(), Scores = [];
  const scores = small ? [60, 70, 70, 85, 90, 0, 100] : null;
  for (let tries = 0; Scores.length < target && tries < target * 20; tries++) {
    const student = (small ? 101 : 1) + pick(students), subject = subjects[pick(subjects.length)], date = dates[pick(dates.length)];
    const key = `${student}|${subject}|${date}`;
    if (seen.has(key)) continue;
    seen.add(key);
    Scores.push([student, subject, scores ? scores[pick(scores.length)] : pick(101), date]);
  }
  return [{ Scores }];
}
